import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"অদ্ভুত শক্তির তিন প্রকার নিষ্পত্তি প্রক্রিয়া","description":"","frontmatter":{},"headers":[],"relativePath":"bn/56-奇异能量三类处置流程.md","filePath":"bn/56-奇异能量三类处置流程.md","lastUpdated":null}'),h={name:"bn/56-奇异能量三类处置流程.md"};function l(i,t,o,n,b,s){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="অদ্ভুত-শক্তির-তিন-প্রকার-নিষ্পত্তি-প্রক্রিয়া" tabindex="-1">অদ্ভুত শক্তির তিন প্রকার নিষ্পত্তি প্রক্রিয়া <a class="header-anchor" href="#অদ্ভুত-শক্তির-তিন-প্রকার-নিষ্পত্তি-প্রক্রিয়া" aria-label="Permalink to &quot;অদ্ভুত শক্তির তিন প্রকার নিষ্পত্তি প্রক্রিয়া&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>56</td></tr><tr><td>মডিউল</td><td>জাতি ও জীবন রূপ</td></tr><tr><td>মূল কীওয়ার্ড</td><td>বিকাশ ও ব্যবহার, সংরক্ষণ ও পর্যবেক্ষণ, বিশুদ্ধকরণ ও নির্মূল, শক্তি নিষ্পত্তি, প্রমিত প্রক্রিয়া</td></tr></tbody></table><h2 id="১-নিষ্পত্তি-প্রক্রিয়ার-সামগ্রিক-নীতি" tabindex="-1">১. নিষ্পত্তি প্রক্রিয়ার সামগ্রিক নীতি <a class="header-anchor" href="#১-নিষ্পত্তি-প্রক্রিয়ার-সামগ্রিক-নীতি" aria-label="Permalink to &quot;১. নিষ্পত্তি প্রক্রিয়ার সামগ্রিক নীতি&quot;">​</a></h2><p>অদ্ভুত শক্তির নিষ্পত্তি অ্যাঙ্কর সিম্বায়োসিস সভ্যতার শক্তি পরিচালনার মূল অংশ। &quot;৫৫-অদ্ভুত শক্তির শ্রেণীবিভাগ ও বৈশিষ্ট্য&quot; এর ঝুঁকি মূল্যায়নের ফলাফল অনুযায়ী, অদ্ভুত শক্তির নিষ্পত্তি তিন প্রকার প্রমিত প্রক্রিয়ায় বিভক্ত: বিকাশ ও ব্যবহার প্রকার, সংরক্ষণ ও পর্যবেক্ষণ প্রকার, বিশুদ্ধকরণ ও নির্মূল প্রকার। তিন প্রকার প্রক্রিয়া যথাক্রমে নিম্ন ঝুঁকি, মাঝারি ঝুঁকি, উচ্চ ঝুঁকি তিন স্তরের সাথে মিলে যায়, ব্যবহার থেকে নিয়ন্ত্রণ এবং তারপর নির্মূল পর্যন্ত একটি সম্পূর্ণ নিষ্পত্তি ব্যবস্থা গঠন করে।</p><p>নিষ্পত্তি প্রক্রিয়া নিম্নলিখিত সামগ্রিক নীতি অনুসরণ করে:</p><table tabindex="0"><thead><tr><th>নীতি</th><th>অন্তর্নিহিত অর্থ</th></tr></thead><tbody><tr><td>নিরাপত্তা প্রথম নীতি</td><td>শক্তি নিষ্পত্তির প্রাথমিক লক্ষ্য হলো নিরাপত্তা নিশ্চিত করা, শক্তি নিয়ন্ত্রণহীন হয়ে ক্ষতি সাধন রোধ করা</td></tr><tr><td>মূল্য সর্বাধিককরণ নীতি</td><td>নিরাপদ ও নিয়ন্ত্রণযোগ্য অবস্থায়, যতটা সম্ভব অদ্ভুত শক্তির মূল্য সর্বাধিককরণ ব্যবহার বাস্তবায়ন করা</td></tr><tr><td>আনুপাতিকতা নীতি</td><td>নিষ্পত্তি ব্যবস্থার তীব্রতা অদ্ভুত শক্তির ঝুঁকি স্তরের সাথে মানানসই হওয়া উচিত</td></tr><tr><td>ন্যূনতম পরিবেশগত প্রভাব নীতি</td><td>নিষ্পত্তি প্রক্রিয়াতে যতটা সম্ভব পরিবেশের উপর প্রভাব কমানো উচিত, শক্তি দূষণ রোধ করা</td></tr><tr><td>সম্পূর্ণ প্রক্রিয়া পর্যবেক্ষণ নীতি</td><td>নিষ্পত্তি প্রক্রিয়া সম্পূর্ণভাবে পর্যবেক্ষণ করা, বাস্তব সময়ে শক্তির অবস্থা উপলব্ধি করা, অস্বাভাবিক পরিস্থিতিতে তাৎক্ষণিক প্রতিক্রিয়া করা</td></tr></tbody></table><h2 id="২-প্রথম-প্রকার-বিকাশ-ও-ব্যবহার-প্রকার-নিষ্পত্তি-প্রক্রিয়া" tabindex="-1">২. প্রথম প্রকার: বিকাশ ও ব্যবহার প্রকার নিষ্পত্তি প্রক্রিয়া <a class="header-anchor" href="#২-প্রথম-প্রকার-বিকাশ-ও-ব্যবহার-প্রকার-নিষ্পত্তি-প্রক্রিয়া" aria-label="Permalink to &quot;২. প্রথম প্রকার: বিকাশ ও ব্যবহার প্রকার নিষ্পত্তি প্রক্রিয়া&quot;">​</a></h2><p>বিকাশ ও ব্যবহার প্রকার নিষ্পত্তি প্রযোজ্য সেই অদ্ভুত শক্তির জন্য যা শনাক্তকরণ ও মূল্যায়নে প্রথম স্তর (নিম্ন ঝুঁকি) হিসেবে চিহ্নিত, অর্থাৎ স্বভাব স্থিতিশীল, ক্ষয়কারী নয়, ব্যবহারযোগ্য, পরিবেশগত প্রভাব নিয়ন্ত্রণযোগ্য শক্তি রূপ।</p><h3 id="১-নিষ্পত্তি-লক্ষ্য" tabindex="-1">(১) নিষ্পত্তি লক্ষ্য <a class="header-anchor" href="#১-নিষ্পত্তি-লক্ষ্য" aria-label="Permalink to &quot;(১) নিষ্পত্তি লক্ষ্য&quot;">​</a></h3><p>অদ্ভুত শক্তিকে সভ্যতার শক্তি সম্পদ ব্যবস্থায় অন্তর্ভুক্ত করা, নিরাপদ ও দক্ষ বিকাশ ও ব্যবহার করা, সিম্বায়োসিস বিবর্তনকে ত্বরান্বিতকারী উপকারী সম্পদে রূপান্তর করা।</p><h3 id="২-নিষ্পত্তি-ধাপ" tabindex="-1">(২) নিষ্পত্তি ধাপ <a class="header-anchor" href="#২-নিষ্পত্তি-ধাপ" aria-label="Permalink to &quot;(২) নিষ্পত্তি ধাপ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ধাপ</th><th>নাম</th><th>বিস্তারিত বিষয়বস্তু</th><th>দায়িত্বপ্রাপ্ত প্রতিষ্ঠান</th></tr></thead><tbody><tr><td>প্রথম ধাপ</td><td>শক্তি সনাক্তকরণ</td><td>অদ্ভুত শক্তির সম্পূর্ণ সনাক্তকরণ করা, এর প্রকার, বৈশিষ্ট্য, বিশুদ্ধতা, ব্যবহারযোগ্য মূল্য ইত্যাদি প্যারামিটার নির্ধারণ করা</td><td>শক্তি পরিচালনা ব্যুরো + সনাক্তকরণ বিশেষজ্ঞ দল</td></tr><tr><td>দ্বিতীয় ধাপ</td><td>নিরাপত্তা মূল্যায়ন</td><td>অদ্ভুত শক্তির বিকাশ ও ব্যবহারের নিরাপত্তা মূল্যায়ন করা, স্থিতিশীলতা, প্রতিক্রিয়াশীলতা, পরিবেশগত প্রভাব ইত্যাদি অন্তর্ভুক্ত</td><td>নিরাপত্তা মূল্যায়ন বিশেষজ্ঞ দল</td></tr><tr><td>তৃতীয় ধাপ</td><td>ব্যবহার পরিকল্পনা</td><td>বিস্তারিত বিকাশ ও ব্যবহার পরিকল্পনা প্রণয়ন করা, ব্যবহার পদ্ধতি, প্রযুক্তিগত পথ, নিরাপত্তা ব্যবস্থা, আর্থিক লাভ বিশ্লেষণ ইত্যাদি অন্তর্ভুক্ত</td><td>শক্তি পরিচালনা ব্যুরো + প্রযুক্তি গবেষণা প্রতিষ্ঠান</td></tr><tr><td>চতুর্থ ধাপ</td><td>পরীক্ষামূলক ব্যবহার</td><td>নিয়ন্ত্রিত পরিবেশে ছোট পরিমাণে পরীক্ষামূলক ব্যবহার করা, পরিকল্পনার সম্ভাব্যতা ও নিরাপত্তা যাচাই করা</td><td>প্রযুক্তি গবেষণা প্রতিষ্ঠান + সাধক</td></tr><tr><td>পঞ্চম ধাপ</td><td>বৃহৎ প্রসার</td><td>পরীক্ষা সফল হওয়ার পর, ধীরে ধীরে ব্যবহারের পরিমাণ বাড়ানো, অদ্ভুত শক্তিকে স্বাভাবিক শক্তি সম্পদ ব্যবস্থায় অন্তর্ভুক্ত করা</td><td>শক্তি পরিচালনা ব্যুরো + সম্পদ পরিচালনা বিভাগ</td></tr><tr><td>ষষ্ঠ ধাপ</td><td>প্রমিত ব্যবস্থাপনা</td><td>অদ্ভুত শক্তির খনন, সংরক্ষণ, পরিবহন, ব্যবহারের মান নির্ধারণ করা, প্রমিত ব্যবস্থাপনা ব্যবস্থায় অন্তর্ভুক্ত করা</td><td>প্রমিত ব্যবস্থাপনা প্রতিষ্ঠান</td></tr><tr><td>সপ্তম ধাপ</td><td>ক্রমাগত পর্যবেক্ষণ</td><td>বিকাশ ও ব্যবহারের সম্পূর্ণ প্রক্রিয়া ক্রমাগত পর্যবেক্ষণ করা, নিয়মিত নিরাপত্তা ও ব্যবহার দক্ষতা মূল্যায়ন করা</td><td>শক্তি পর্যবেক্ষণ নেটওয়ার্ক</td></tr></tbody></table><h3 id="৩-প্রধান-ব্যবহার-দিক" tabindex="-1">(৩) প্রধান ব্যবহার দিক <a class="header-anchor" href="#৩-প্রধান-ব্যবহার-দিক" aria-label="Permalink to &quot;(৩) প্রধান ব্যবহার দিক&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ব্যবহার দিক</th><th>প্রযোজ্য শক্তি প্রকার</th><th>বিস্তারিত ব্যবহার</th></tr></thead><tbody><tr><td>সাধন সম্পদ</td><td>মৌলিক রূপান্তর প্রকার, নিয়ম-উৎপন্ন প্রকার</td><td>উচ্চ পর্যায়ের সাধকদের সাধন সম্পদ হিসেবে, সাধন দক্ষতা ও পর্যায় বৃদ্ধি</td></tr><tr><td>জ্বালানি সরবরাহ</td><td>স্থিতিশীল প্রকার অদ্ভুত শক্তি</td><td>স্বাভাবিক জ্বালানিতে রূপান্তর, শহর, মৌলিক অবকাঠামো, মাতৃকা বিকাশে জ্বালানি সরবরাহ</td></tr><tr><td>প্রযুক্তিগত প্রয়োগ</td><td>স্থান শক্তি, সময় শক্তি</td><td>স্থান নিয়ম প্রযুক্তি, আন্তঃমাতৃকা যোগাযোগ, সময় প্রত্যাবর্তন ইত্যাদি উচ্চ পর্যায়ের প্রযুক্তিতে ব্যবহার</td></tr><tr><td>চিকিৎসা প্রয়োগ</td><td>পবিত্র আলো শক্তি, ইচ্ছাশক্তি</td><td>গুরুতর আঘাত নিরাময়, নেতিবাচক শক্তি বিশুদ্ধকরণ, মানসিক চিকিৎসা ইত্যাদি চিকিৎসা ক্ষেত্রে ব্যবহার</td></tr><tr><td>অস্ত্র ও সরঞ্জাম</td><td>বেগুনি বজ্র, প্রবল বায়ু</td><td>উচ্চ পর্যায়ের অস্ত্র ও প্রতিরক্ষা সরঞ্জাম তৈরিতে, সভ্যতার প্রতিরক্ষা ক্ষমতা বৃদ্ধি</td></tr><tr><td>বৈজ্ঞানিক গবেষণা</td><td>বিভিন্ন প্রকার অদ্ভুত শক্তি</td><td>মৌলিক বিজ্ঞান গবেষণা, নিয়ম গবেষণা, মহাজাগতিক গবেষণা ইত্যাদি একাডেমিক ক্ষেত্রে ব্যবহার</td></tr></tbody></table><h3 id="৪-ব্যবহার-নিরাপত্তা-বিধি" tabindex="-1">(৪) ব্যবহার নিরাপত্তা বিধি <a class="header-anchor" href="#৪-ব্যবহার-নিরাপত্তা-বিধি" aria-label="Permalink to &quot;(৪) ব্যবহার নিরাপত্তা বিধি&quot;">​</a></h3><ul><li>অদ্ভুত শক্তির খনন অবশ্যই পেশাদার কর্মীদের নির্দেশনায় সঞ্চালিত হতে হবে, প্রয়োজনীয় সুরক্ষা সরঞ্জাম ও জরুরি সরঞ্জাম সজ্জিত করতে হবে।</li><li>অদ্ভুত শক্তির সংরক্ষণে অবশ্যই বিশেষ শক্তি সংরক্ষণ যন্ত্র ব্যবহার করতে হবে, সংরক্ষণ সুবিধায় শক্তি পর্দা ও নিরাপত্তা সুরক্ষা ব্যবস্থা সজ্জিত করতে হবে।</li><li>অদ্ভুত শক্তির পরিবহনে অবশ্যই বিশেষ শক্তি পরিবহন পাত্র ব্যবহার করতে হবে, পরিবহন রুট জনবহুল অঞ্চল ও পরিবেশগত সংবেদনশীল অঞ্চল এড়াতে হবে।</li><li>অদ্ভুত শক্তির ব্যবহার অবশ্যই অপারেটিং প্রক্রিয়া মেনে চলতে হবে, অতিরিক্ত ব্যবহার বা বিধি ভঙ্গ করা নিষিদ্ধ।</li><li>অদ্ভুত শক্তি ব্যবহার দুর্ঘটনা জরুরি পরিকল্পনা প্রতিষ্ঠা করা, নিয়মিত জরুরি অনুশীলন করা।</li></ul><h2 id="৩-দ্বিতীয়-প্রকার-সংরক্ষণ-ও-পর্যবেক্ষণ-প্রকার-নিষ্পত্তি-প্রক্রিয়া" tabindex="-1">৩. দ্বিতীয় প্রকার: সংরক্ষণ ও পর্যবেক্ষণ প্রকার নিষ্পত্তি প্রক্রিয়া <a class="header-anchor" href="#৩-দ্বিতীয়-প্রকার-সংরক্ষণ-ও-পর্যবেক্ষণ-প্রকার-নিষ্পত্তি-প্রক্রিয়া" aria-label="Permalink to &quot;৩. দ্বিতীয় প্রকার: সংরক্ষণ ও পর্যবেক্ষণ প্রকার নিষ্পত্তি প্রক্রিয়া&quot;">​</a></h2><p>সংরক্ষণ ও পর্যবেক্ষণ প্রকার নিষ্পত্তি প্রযোজ্য সেই অদ্ভুত শক্তির জন্য যা শনাক্তকরণ ও মূল্যায়নে দ্বিতীয় স্তর (মাঝারি ঝুঁকি) হিসেবে চিহ্নিত, অর্থাৎ স্বভাব তুলনামূলকভাবে সক্রিয়, কিছু ক্ষয়কারী বা বিস্তারকারী, নিয়ন্ত্রণ প্রয়োজন এমন শক্তি রূপ।</p><h3 id="১-নিষ্পত্তি-লক্ষ্য-1" tabindex="-1">(১) নিষ্পত্তি লক্ষ্য <a class="header-anchor" href="#১-নিষ্পত্তি-লক্ষ্য-1" aria-label="Permalink to &quot;(১) নিষ্পত্তি লক্ষ্য&quot;">​</a></h3><p>নিরাপত্তা নিশ্চিত করার অবস্থায়, অদ্ভুত শক্তি সংরক্ষণ ও ক্রমাগত পর্যবেক্ষণ করা, এর বিস্তার বা ক্ষতি সাধন রোধ করা; একই সাথে ক্রমাগত গবেষণা করা, নিরাপদ ব্যবহার বা বিশুদ্ধকরণের সম্ভাবনা অন্বেষণ করা।</p><h3 id="২-নিষ্পত্তি-ধাপ-1" tabindex="-1">(২) নিষ্পত্তি ধাপ <a class="header-anchor" href="#২-নিষ্পত্তি-ধাপ-1" aria-label="Permalink to &quot;(২) নিষ্পত্তি ধাপ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ধাপ</th><th>নাম</th><th>বিস্তারিত বিষয়বস্তু</th><th>দায়িত্বপ্রাপ্ত প্রতিষ্ঠান</th></tr></thead><tbody><tr><td>প্রথম ধাপ</td><td>শক্তি সংযতকরণ</td><td>বিশেষ শক্তি সংযতকরণ যন্ত্র ব্যবহার করে অদ্ভুত শক্তি সংরক্ষণ করা, এর বিস্তার রোধ করা</td><td>স্থানীয় নিষ্পত্তি দল + প্রযুক্তি বিশেষজ্ঞ দল</td></tr><tr><td>দ্বিতীয় ধাপ</td><td>স্থানান্তর ও পরিবহন</td><td>সংরক্ষিত অদ্ভুত শক্তি বিশেষ শক্তি সংরক্ষণ সুবিধায় স্থানান্তর করা, পরিবহন প্রক্রিয়া সম্পূর্ণভাবে পর্যবেক্ষণ করা</td><td>শক্তি পরিচালনা ব্যুরো + নিরাপত্তা সুরক্ষা বিভাগ</td></tr><tr><td>তৃতীয় ধাপ</td><td>সুবিধা সংরক্ষণ</td><td>অদ্ভুত শক্তি বিশেষ সংরক্ষণ সুবিধায় জমা করা, সুবিধায় বহু স্তরের শক্তি পর্দা, স্থান স্থিরকরণ, নিরাপত্তা সুরক্ষা ব্যবস্থা সজ্জিত</td><td>শক্তি সংরক্ষণ সুবিধা পরিচালনা প্রতিষ্ঠান</td></tr><tr><td>চতুর্থ ধাপ</td><td>ক্রমাগত পর্যবেক্ষণ</td><td>সংরক্ষিত অদ্ভুত শক্তি ২৪ ঘণ্টা ক্রমাগত পর্যবেক্ষণ করা, বাস্তব সময়ে শক্তির ওঠানামা, তাপমাত্রা, চাপ ইত্যাদি প্যারামিটার পর্যবেক্ষণ করা</td><td>পর্যবেক্ষণ দল</td></tr><tr><td>পঞ্চম ধাপ</td><td>নিয়মিত পরীক্ষা</td><td>নিয়মিত অদ্ভুত শক্তি পরীক্ষা করা, এর স্থিতিশীলতা ও ঝুঁকি স্তরের পরিবর্তন মূল্যায়ন করা</td><td>সনাক্তকরণ বিশেষজ্ঞ দল</td></tr><tr><td>ষষ্ঠ ধাপ</td><td>গবেষণা ও অন্বেষণ</td><td>নিয়ন্ত্রিত অবস্থায় অদ্ভুত শক্তি গবেষণা করা, নিরাপদ ব্যবহার বা বিশুদ্ধকরণ ও নির্মূলের প্রযুক্তিগত পথ অন্বেষণ করা</td><td>বৈজ্ঞানিক গবেষণা প্রতিষ্ঠান</td></tr><tr><td>সপ্তম ধাপ</td><td>প্রকার রূপান্তর</td><td>গবেষণা ও পর্যবেক্ষণের ফলাফল অনুযায়ী, ঝুঁকি প্রথম স্তরে নেমে গেলে বিকাশ ও ব্যবহার প্রকারে রূপান্তর, ঝুঁকি তৃতীয় স্তরে বাড়লে বিশুদ্ধকরণ ও নির্মূল প্রকারে রূপান্তর</td><td>শক্তি পরিচালনা ব্যুরো + অদ্ভুত জীবন বিচার আদালত</td></tr></tbody></table><h3 id="৩-সংরক্ষণ-সুবিধার-মান" tabindex="-1">(৩) সংরক্ষণ সুবিধার মান <a class="header-anchor" href="#৩-সংরক্ষণ-সুবিধার-মান" aria-label="Permalink to &quot;(৩) সংরক্ষণ সুবিধার মান&quot;">​</a></h3><ul><li><strong>স্থান নির্বাচনের মান</strong>: সংরক্ষণ সুবিধার স্থান জনবহুল, ভূতাত্ত্বিকভাবে স্থিতিশীল, শক্তি পরিবেশ স্থিতিশীল অঞ্চলে নির্বাচন করতে হবে, পরিবেশ সংরক্ষণ অঞ্চল ও গুরুত্বপূর্ণ মৌলিক অবকাঠামো থেকে দূরে রাখতে হবে।</li><li><strong>নির্মাণ মান</strong>: সংরক্ষণ সুবিধা বহু স্তরের সুরক্ষা কাঠামো ব্যবহার করবে, যার মধ্যে ভৌত বাধা, শক্তি বাধা, স্থান লক তিন স্তরের সুরক্ষা অন্তর্ভুক্ত, শক্তি ফুটো না হওয়া নিশ্চিত করা।</li><li><strong>যন্ত্রের মান</strong>: উচ্চ নির্ভুলতার শক্তি পর্যবেক্ষণ যন্ত্র, স্বয়ংক্রিয় সংযতকরণ ব্যবস্থা, জরুরি বিশুদ্ধকরণ ব্যবস্থা, সংরক্ষিত জ্বালানি ব্যবস্থা ইত্যাদি পেশাদার সরঞ্জাম সজ্জিত করতে হবে।</li><li><strong>ব্যবস্থাপনা মান</strong>: কঠোর প্রবেশ-প্রস্থান ব্যবস্থাপনা ও অপারেটিং বিধি প্রয়োগ করা, শুধুমাত্র অনুমোদিত পেশাদার কর্মীরা সংরক্ষণ অঞ্চলে প্রবেশ করতে পারবে।</li><li><strong>জরুরি মান</strong>: সম্পূর্ণ জরুরি পরিকল্পনা ও জরুরি সরঞ্জাম সজ্জিত করতে হবে, যার মধ্যে শক্তি ফুটো জরুরি ব্যবস্থা, বিস্ফোরণ জরুরি প্রতিক্রিয়া, কর্মী সরণ পরিকল্পনা ইত্যাদি অন্তর্ভুক্ত।</li></ul><h3 id="৪-দীর্ঘমেয়াদি-সংরক্ষণ-ব্যবস্থাপনা" tabindex="-1">(৪) দীর্ঘমেয়াদি সংরক্ষণ ব্যবস্থাপনা <a class="header-anchor" href="#৪-দীর্ঘমেয়াদি-সংরক্ষণ-ব্যবস্থাপনা" aria-label="Permalink to &quot;(৪) দীর্ঘমেয়াদি সংরক্ষণ ব্যবস্থাপনা&quot;">​</a></h3><p>যে অদ্ভুত শক্তি দীর্ঘমেয়াদি গবেষণার পরও নিরাপদে ব্যবহার বা বিশুদ্ধকরণ ও নির্মূল করা যায় না, তার জন্য দীর্ঘমেয়াদি সংরক্ষণ ব্যবস্থাপনা প্রয়োগ করা হয়:</p><ul><li>দীর্ঘমেয়াদি সংরক্ষিত অদ্ভুত শক্তি প্রতি বছর একবার সম্পূর্ণ পরীক্ষা ও ঝুঁকি মূল্যায়ন করা হয়।</li><li>সংরক্ষণ সুবিধা প্রতি পাঁচ বছরে একবার সম্পূর্ণ মেরামত ও উন্নয়ন করা হয়, সুবিধার নিরাপত্তা ও নির্ভরযোগ্যতা নিশ্চিত করা হয়।</li><li>দীর্ঘমেয়াদি সংরক্ষিত অদ্ভুত শক্তির তথ্য সভ্যতার শক্তি সম্পদ নথিভুক্ত করা হয়, নিয়মিত একাডেমিক বিনিময় ও গবেষণা সহযোগিতা করা হয়।</li><li>যদি নতুন প্রযুক্তিগত উপায় দীর্ঘমেয়াদি সংরক্ষিত অদ্ভুত শক্তি নিরাপদে ব্যবহার বা বিশুদ্ধকরণ ও নির্মূল করতে পারে, তবে অবিলম্বে পুনর্মূল্যায়ন ও নিষ্পত্তি প্রক্রিয়া শুরু করা উচিত।</li></ul><h2 id="৪-তৃতীয়-প্রকার-বিশুদ্ধকরণ-ও-নির্মূল-প্রকার-নিষ্পত্তি-প্রক্রিয়া" tabindex="-1">৪. তৃতীয় প্রকার: বিশুদ্ধকরণ ও নির্মূল প্রকার নিষ্পত্তি প্রক্রিয়া <a class="header-anchor" href="#৪-তৃতীয়-প্রকার-বিশুদ্ধকরণ-ও-নির্মূল-প্রকার-নিষ্পত্তি-প্রক্রিয়া" aria-label="Permalink to &quot;৪. তৃতীয় প্রকার: বিশুদ্ধকরণ ও নির্মূল প্রকার নিষ্পত্তি প্রক্রিয়া&quot;">​</a></h2><p>বিশুদ্ধকরণ ও নির্মূল প্রকার নিষ্পত্তি প্রযোজ্য সেই অদ্ভুত শক্তির জন্য যা শনাক্তকরণ ও মূল্যায়নে তৃতীয় স্তর (উচ্চ ঝুঁকি) হিসেবে চিহ্নিত, অর্থাৎ ক্ষয়কারী/গ্রাসকারী/সংক্রামক শক্তিশালী, নিয়ন্ত্রণহীন, পরিবেশ বিনাশ গুরুতর এমন শক্তি রূপ। চতুর্থ স্তর (অত্যন্ত উচ্চ ঝুঁকি) এর অদ্ভুত শক্তির জন্য জরুরি নির্মূল প্রক্রিয়া প্রযোজ্য।</p><h3 id="১-নিষ্পত্তি-লক্ষ্য-2" tabindex="-1">(১) নিষ্পত্তি লক্ষ্য <a class="header-anchor" href="#১-নিষ্পত্তি-লক্ষ্য-2" aria-label="Permalink to &quot;(১) নিষ্পত্তি লক্ষ্য&quot;">​</a></h3><p>বিশুদ্ধকরণ বা নির্মূলের মাধ্যমে, অদ্ভুত শক্তির বিপজ্জনকতা নির্মূল করা, তাকে ক্ষতিকর মৌলিক শক্তিতে রূপান্তর বা সম্পূর্ণরূপে নির্মূল করা, সভ্যতা ও পরিবেশের নিরাপত্তা রক্ষা করা।</p><h3 id="২-নিষ্পত্তি-পদ্ধতি" tabindex="-1">(২) নিষ্পত্তি পদ্ধতি <a class="header-anchor" href="#২-নিষ্পত্তি-পদ্ধতি" aria-label="Permalink to &quot;(২) নিষ্পত্তি পদ্ধতি&quot;">​</a></h3><p>বিশুদ্ধকরণ ও নির্মূল প্রকার নিষ্পত্তি দুই পদ্ধতিতে বিভক্ত, অদ্ভুত শক্তির নির্দিষ্ট পরিস্থিতি অনুযায়ী নির্বাচন করা হয়:</p><table tabindex="0"><thead><tr><th>পদ্ধতি</th><th>নাম</th><th>প্রযোজ্য পরিস্থিতি</th><th>বিস্তারিত পদ্ধতি</th></tr></thead><tbody><tr><td>পদ্ধতি এক</td><td>শক্তি বিশুদ্ধকরণ</td><td>যে অদ্ভুত শক্তি বিশুদ্ধ করা যায় এবং বিশুদ্ধকরণের পর ব্যবহারযোগ্য</td><td>পবিত্র আলো শক্তি, ইচ্ছাশক্তি ইত্যাদি বিশুদ্ধকরণ শক্তি ব্যবহার করা, বা বিশেষ বিশুদ্ধকরণ যন্ত্র ও মন্ত্র, অদ্ভুত শক্তির বিপজ্জনক বৈশিষ্ট্য বিশুদ্ধ করে অপসারণ করা, ক্ষতিকর ব্যবহারযোগ্য স্বাভাবিক শক্তিতে রূপান্তর করা</td></tr><tr><td>পদ্ধতি দুই</td><td>শক্তি নির্মূল</td><td>যে অদ্ভুত শক্তি বিশুদ্ধ করা যায় না বা বিশুদ্ধকরণের ঝুঁকি অত্যধিক</td><td>বিশেষ নির্মূল যন্ত্র বা মন্ত্র ব্যবহার করা, অদ্ভুত শক্তিকে মৌলিক কণা বা শূন্যতায় বিশ্লেষণ করা, সম্পূর্ণরূপে এর অস্তিত্ব ও বিপজ্জনকতা নির্মূল করা</td></tr></tbody></table><h3 id="৩-নিষ্পত্তি-ধাপ" tabindex="-1">(৩) নিষ্পত্তি ধাপ <a class="header-anchor" href="#৩-নিষ্পত্তি-ধাপ" aria-label="Permalink to &quot;(৩) নিষ্পত্তি ধাপ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ধাপ</th><th>নাম</th><th>বিস্তারিত বিষয়বস্তু</th><th>দায়িত্বপ্রাপ্ত প্রতিষ্ঠান</th></tr></thead><tbody><tr><td>প্রথম ধাপ</td><td>নিষ্পত্তি অনুমোদন</td><td>উচ্চ ঝুঁকির অদ্ভুত শক্তির বিশুদ্ধকরণ ও নির্মূল অবশ্যই শক্তি পরিচালনা ব্যুরো ও অদ্ভুত জীবন বিচার আদালতের যৌথ অনুমোদন প্রয়োজন, অত্যন্ত উচ্চ ঝুঁকি প্রথমে নিষ্পত্তি করে পরে অনুমোদন পূরণ করা যায়</td><td>শক্তি পরিচালনা ব্যুরো + অদ্ভুত জীবন বিচার আদালত</td></tr><tr><td>দ্বিতীয় ধাপ</td><td>পরিকল্পনা প্রণয়ন</td><td>বিস্তারিত বিশুদ্ধকরণ ও নির্মূল পরিকল্পনা প্রণয়ন করা, নিষ্পত্তি পদ্ধতি, প্রযুক্তিগত উপায়, নিরাপত্তা ব্যবস্থা, জরুরি পরিকল্পনা, পরিবেশগত প্রভাব মূল্যায়ন ইত্যাদি অন্তর্ভুক্ত</td><td>প্রযুক্তি বিশেষজ্ঞ দল + নিরাপত্তা মূল্যায়ন বিশেষজ্ঞ দল</td></tr><tr><td>তৃতীয় ধাপ</td><td>নিরাপদ বিচ্ছিন্নতা</td><td>অদ্ভুত শক্তি বিশেষ বিশুদ্ধকরণ ও নির্মূল সুবিধায় স্থানান্তর করা, সুবিধায় সর্বোচ্চ স্তরের নিরাপত্তা সুরক্ষা ও শক্তি সংযতকরণ যন্ত্র সজ্জিত</td><td>স্থানীয় নিষ্পত্তি দল</td></tr><tr><td>চতুর্থ ধাপ</td><td>বিশুদ্ধকরণ ও নির্মূল</td><td>পরিকল্পনা অনুযায়ী বিশুদ্ধকরণ ও নির্মূল বাস্তবায়ন করা, প্রক্রিয়া সম্পূর্ণভাবে পর্যবেক্ষণ করা, একবার অস্বাভাবিক দেখা দিলে তাৎক্ষণিক জরুরি পরিকল্পনা শুরু করা</td><td>প্রযুক্তি বিশেষজ্ঞ দল + উচ্চ পর্যায়ের সাধক</td></tr><tr><td>পঞ্চম ধাপ</td><td>উৎপাদ ব্যবস্থাপনা</td><td>বিশুদ্ধকরণ ও নির্মূল থেকে উৎপন্ন শক্তি ও পদার্থ পরীক্ষা করা, ব্যবহারযোগ্য সম্পদ মজুতে অন্তর্ভুক্ত করা, ক্ষতিকর স্বাভাবিক নির্গমন, ক্ষতিকর নিরাপদ নিষ্পত্তি করা</td><td>সম্পদ পরিচালনা প্রতিষ্ঠান + পরিবেশ বিভাগ</td></tr><tr><td>ষষ্ঠ ধাপ</td><td>পরিবেশ পুনরুদ্ধার</td><td>নিষ্পত্তি প্রক্রিয়াতে প্রভাবিত পরিবেশ পুনরুদ্ধার করা, পরিবেশ ও শক্তি ভারসাম্য পুনরুদ্ধার করা</td><td>পরিবেশ বিভাগ</td></tr><tr><td>সপ্তম ধাপ</td><td>নথি সংরক্ষণ</td><td>নিষ্পত্তি সম্পূর্ণ প্রক্রিয়ার রেকর্ড, ডেটা, রিপোর্ট সংগ্রহ করে সংরক্ষণ করা, সম্পূর্ণ নিষ্পত্তি নথি তৈরি করা</td><td>শক্তি পরিচালনা ব্যুরো</td></tr></tbody></table><h3 id="৪-জরুরি-নির্মূল-প্রক্রিয়া" tabindex="-1">(৪) জরুরি নির্মূল প্রক্রিয়া <a class="header-anchor" href="#৪-জরুরি-নির্মূল-প্রক্রিয়া" aria-label="Permalink to &quot;(৪) জরুরি নির্মূল প্রক্রিয়া&quot;">​</a></h3><p>চতুর্থ স্তর (অত্যন্ত উচ্চ ঝুঁকি) এর অদ্ভুত শক্তি, অর্থাৎ মহাজাগতিক বিনাশকারী, নিয়ম-স্তরের হুমকিস্বরূপ, নিয়ন্ত্রণহীন, সরাসরি সভ্যতার বেঁচে থাকাকে হুমকি দেওয়া এমন অদ্ভুত শক্তির জন্য, জরুরি নির্মূল প্রক্রিয়া প্রযোজ্য:</p><p>১. স্থানীয় সর্বোচ্চ স্তরের দায়িত্বপ্রাপ্ত ব্যক্তি সরাসরি জরুরি নির্মূল শুরু করার আদেশ দিতে পারেন, পূর্বে অনুমোদনের প্রয়োজন নেই, কিন্তু নিষ্পত্তির পর ২৪ ঘণ্টার মধ্যে শক্তি পরিচালনা ব্যুরো ও অদ্ভুত জীবন বিচার আদালতে রিপোর্ট জমা দিতে হবে। ২. জরুরি নির্মূলে সভ্যতার সর্বোচ্চ স্তরের অস্ত্র ও শক্তি সম্পদ ব্যবহার করা যায়, যার মধ্যে মাতৃকা সর্বোচ্চ শক্তিশালীদের যৌথ হস্তক্ষেপ ও অ্যাঙ্কর শক্তির কেন্দ্রিক ব্যবহার অন্তর্ভুক্ত। ৩. জরুরি নির্মূলের অগ্রাধিকার লক্ষ্য হলো হুমকি নির্মূল করা, জীবন ও সভ্যতার নিরাপত্তা রক্ষা করা, শক্তির পুনরুদ্ধার ও ব্যবহার চাওয়া হয় না। ৪. জরুরি নির্মূলের পর সম্পূর্ণ পরিবেশ মূল্যায়ন ও পুনরুদ্ধার করা উচিত, গৌণ দুর্যোগ ও শক্তি অবশিষ্টতা রোধ করা। ৫. জরুরি নির্মূলের কেস অবশ্যই ব্যক্তিগত পর্যালোচনা ও বিশ্লেষণ করা উচিত, অভিজ্ঞতা ও শিক্ষা সংগ্রহ করা, সতর্কতা ও নিষ্পত্তি ব্যবস্থা উন্নত করা।</p><h3 id="৫-প্রধান-বিশুদ্ধকরণ-ও-নির্মূল-প্রযুক্তি" tabindex="-1">(৫) প্রধান বিশুদ্ধকরণ ও নির্মূল প্রযুক্তি <a class="header-anchor" href="#৫-প্রধান-বিশুদ্ধকরণ-ও-নির্মূল-প্রযুক্তি" aria-label="Permalink to &quot;(৫) প্রধান বিশুদ্ধকরণ ও নির্মূল প্রযুক্তি&quot;">​</a></h3><table tabindex="0"><thead><tr><th>প্রযুক্তির নাম</th><th>নীতি</th><th>প্রযোজ্য শক্তি প্রকার</th></tr></thead><tbody><tr><td>পবিত্র আলো বিশুদ্ধকরণ মন্ত্র</td><td>পবিত্র আলো শক্তির বিশুদ্ধকরণ বৈশিষ্ট্য ব্যবহার করা, অন্ধকার ও নেতিবাচক শক্তিকে প্রশমিত ও নির্মূল করা</td><td>অতল গহ্বর শক্তি, অভিশাপ শক্তি, মৃত্যু জল</td></tr><tr><td>ইচ্ছাশক্তি বিশুদ্ধকরণ বৃত্ত</td><td>সমষ্টিগত ইচ্ছাশক্তি ব্যবহার করে বিশুদ্ধকরণ মন্ডল তৈরি করা, মৃদুভাবে অস্বাভাবিক শক্তি বিশুদ্ধ করা</td><td>চেতনা প্রক্ষেপণ প্রকার, হালকা ক্ষয়কারী প্রকার</td></tr><tr><td>শক্তি বিরোধ পদ্ধতি</td><td>অদ্ভুত শক্তির বৈশিষ্ট্যের বিপরীত শক্তি ব্যবহার করে বিরোধ করা, পরস্পর নির্মূল করা</td><td>মৌলিক রূপান্তর প্রকার, বিপরীত বৈশিষ্ট্যের শক্তি</td></tr><tr><td>নিয়ম নির্মূল মন্ত্র</td><td>স্থান বা সময় নিয়ম আহ্বান করা, অদ্ভুত শক্তিকে অস্থানে নির্বাসিত করা বা এর ক্ষয় ত্বরান্বিত করা</td><td>নিয়ম-উৎপন্ন প্রকার, উচ্চ ঘনত্বের শক্তি</td></tr><tr><td>অ্যাঙ্কর নির্মূল বৃত্ত</td><td>অ্যাঙ্কর শক্তির মৌলিক বৈশিষ্ট্য ব্যবহার করা, অদ্ভুত শক্তিকে বিশ্লেষণ করে মহাজাগতিক মূলতে ফিরিয়ে দেওয়া</td><td>বিভিন্ন উচ্চ ঝুঁকির অদ্ভুত শক্তি</td></tr><tr><td>যান্ত্রিক নির্মূল যন্ত্র</td><td>উচ্চ প্রযুক্তির শক্তি নির্মূল যন্ত্র ব্যবহার করা, ভৌত উপায়ে শক্তি কাঠামো বিশ্লেষণ করা</td><td>স্থিতিশীল প্রকার, ভৌতভাবে প্রক্রিয়াযোগ্য শক্তি</td></tr></tbody></table><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>অদ্ভুত শক্তির তিন প্রকার নিষ্পত্তি প্রক্রিয়া অ্যাঙ্কর সিম্বায়োসিস সভ্যতার শক্তি পরিচালনার প্রমিত অপারেটিং ব্যবস্থা। বিকাশ ও ব্যবহারের মূল্য রূপান্তর থেকে, সংরক্ষণ ও পর্যবেক্ষণের সতর্ক নিয়ন্ত্রণ, এবং তারপর বিশুদ্ধকরণ ও নির্মূলের নিরাপদ নির্মূল পর্যন্ত, তিন প্রকার প্রক্রিয়া সম্পূর্ণ শক্তি ঝুঁকি প্রতিক্রিয়া শৃঙ্খলা গঠন করে, যা অদ্ভুত শক্তির সম্ভাব্য মূল্য সম্পূর্ণরূপে খনন করার পাশাপাশি সভ্যতার নিরাপত্তার সীমানা দৃঢ়ভাবে রক্ষা করে, &quot;ব্যবহার ও নিয়ন্ত্রণ সমান গুরুত্ব, বিকাশ ও নিরাপত্তা একসাথে বিবেচনা&quot; এর শক্তি পরিচালনা লক্ষ্য বাস্তবায়ন করে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>৫৫-অদ্ভুত শক্তির শ্রেণীবিভাগ ও বৈশিষ্ট্য</li><li>৫৪-অদ্ভুত জীবনের তিন প্রকার নিষ্পত্তি প্রক্রিয়া</li><li>১৫-শক্তি চক্র ও রূপান্তর নিয়ম</li><li>৬৫-শক্তি প্রমিতকরণ ও পরিমাপ</li></ul>',45)])])}const q=d(h,[["render",l]]);export{c as __pageData,q as default};
